import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const AJV_OPTIONS = {strict: false, validateFormats: false, allErrors: true} as ConstructorParameters<typeof Ajv>[0];

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv(AJV_OPTIONS);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private compileDynamicSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    try {
      const validate = this.ajv.compile(schema);
      this.validators.set(schema, validate);
      return validate;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}`, {cause: error});
    }
  }

  private compileStaticSchema(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      const validate = new Ajv(AJV_OPTIONS).compile(schema);
      return validate;
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${name}`, {cause: error});
    }
  }

  private describeValidationError(error: ErrorObject, schema: Record<string, unknown>): string {
    const escapeSegment = (segment: string): string => segment.replace(/~/g, '~0').replace(/\//g, '~1');
    const instancePath = 'instancePath' in error ? error.instancePath : undefined;
    const dataPath = 'dataPath' in error ? error.dataPath : undefined;
    const legacyPath =
      typeof dataPath === 'string'
        ? dataPath.replace(
            /\.([^.[\]]+)|\[(\d+)\]|\[['"]([^'"]+)['"]\]/g,
            (_match, dotted, index, quoted) => `/${escapeSegment(String(dotted ?? index ?? quoted))}`
          )
        : undefined;
    const path = typeof instancePath === 'string' && instancePath ? instancePath : (legacyPath ?? '/');
    const params = error.params as Record<string, unknown>;
    const descriptions: Record<string, () => string> = {
      required: () => {
        const missingProperty = String(params.missingProperty);
        const segments = path
          .split('/')
          .slice(1)
          .map(segment => segment.replace(/~1/g, '/').replace(/~0/g, '~'));
        const containingSchema = segments.reduce<Record<string, unknown>>((current, segment) => {
          const properties = current.properties as Record<string, Record<string, unknown>> | undefined;
          return properties?.[segment] ?? {};
        }, schema);
        const hasLiteralRequiredName =
          Array.isArray(containingSchema.required) && containingSchema.required.includes(missingProperty);
        const propertyName =
          typeof instancePath === 'string' || hasLiteralRequiredName
            ? missingProperty
            : missingProperty.replace(/^\./, '');
        return `${path === '/' ? '' : path}/${escapeSegment(propertyName)} is required`;
      },
      additionalProperties: () =>
        `${path === '/' ? '' : path}/${escapeSegment(String(params.additionalProperty))} violates additionalProperties`,
      type: () => `${path} must be ${String(params.type)}`,
    };
    return descriptions[error.keyword]?.() ?? `${path} violates ${error.keyword}`;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : this.compileStaticSchema(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input as specified in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    const validate = tool.validate ?? this.compileDynamicSchema(name, schema);
    if (!validate(input)) {
      const failures = (validate.errors ?? []).map(error => this.describeValidationError(error, schema));
      const result = failures.join('; ');
      log.warn('tool', 'input rejected', {name, failures: result});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import Ajv, {type ValidateFunction} from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry nested legacy required property paths', () => {
  // specs/hal-engine-tool-input-validation/spec.md#16
  it('preserves a leading dot in a nested required property with a legacy dataPath error', async () => {
    const validate = Object.assign(() => false, {
      errors: [{keyword: 'required', dataPath: '.details', params: {missingProperty: '.location'}}],
    });
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validate as unknown as ValidateFunction);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {details: {type: 'object', properties: {'.location': {type: 'string'}}, required: ['.location']}},
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {details: {}});
    compile.mockRestore();

    expect(response.result).toBe('/details/.location is required');
  });
});

import Ajv, {type ValidateFunction} from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

function mockValidationError(keyword: string, dataPath: string, params: Record<string, unknown>) {
  const validate = Object.assign(() => false, {errors: [{keyword, dataPath, params}]});
  return jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validate as unknown as ValidateFunction);
}

describe('ToolRegistry schema registration', () => {
  // specs/hal-engine-tool-input-validation/spec.md#4
  it('names a wrong-typed top-level property from an Ajv dataPath error', async () => {
    const compile = mockValidationError('type', '.unit', {type: 'string'});
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {unit: {type: 'string'}}},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {unit: 42});
    compile.mockRestore();

    expect(response.result).toBe('/unit must be string');
  });

  // specs/hal-engine-tool-input-validation/spec.md#5
  it('preserves a dotted property name from an Ajv bracket dataPath', async () => {
    const compile = mockValidationError('type', "['account.id']", {type: 'string'});
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Lookup',
        inputSchema: {type: 'object', properties: {'account.id': {type: 'string'}}},
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup', {'account.id': 42});
    compile.mockRestore();

    expect(response.result).toBe('/account.id must be string');
  });

  // specs/hal-engine-tool-input-validation/spec.md#6
  it('strips a leading dot from an Ajv required property name', async () => {
    const compile = mockValidationError('required', '', {missingProperty: '.location'});
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {});
    compile.mockRestore();

    expect(response.result).toBe('/location is required');
  });

  // specs/hal-engine-tool-input-validation/spec.md#7
  it('reports every failing field path and constraint for one invalid call', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, unit: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {unit: 42});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/\/location is required; \/unit must be string/),
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#2
  it('escapes a required property name in the reported JSON Pointer path', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {'account/id': {type: 'string'}},
          required: ['account/id'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: '/account~1id is required',
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#11
  it('rejects an invalid static schema before registering the named tool', () => {
    const registry = new ToolRegistry();

    let errorMessage = '';
    try {
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      );
    } catch (error) {
      errorMessage = (error as Error).message;
    }

    expect({errorMessage, registered: registry.has('broken_weather')}).toEqual({
      errorMessage: expect.stringMatching(/broken_weather/),
      registered: false,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#13
  it('validates each resolved schema and reuses a validator for the same schema object', async () => {
    const registry = new ToolRegistry();
    const firstSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const secondSchema = {type: 'object', properties: {zip: {type: 'string'}}, required: ['zip']};
    let schema: ToolDefinition['inputSchema'] = firstSchema;
    let executorCalls = 0;
    registry.register(
      () => ({name: 'lookup', description: 'Lookup', inputSchema: schema}),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const first = await registry.execute('lookup', {});
    schema = secondSchema;
    const second = await registry.execute('lookup', {});
    const third = await registry.execute('lookup', {zip: '12345'});

    const calls = compile.mock.calls;
    const compilationCount = calls.length;
    expect({
      first: first.result,
      second: second.result,
      third: third.result,
      executorCalls,
      compiled: compilationCount,
    }).toEqual({
      first: expect.stringMatching(/location.*required|required.*location/),
      second: expect.stringMatching(/zip.*required|required.*zip/),
      third: 'ok',
      executorCalls: 1,
      compiled: 2,
    });
    compile.mockRestore();
  });

  // specs/hal-engine-tool-input-validation/spec.md#14
  it('names the path of an explicitly forbidden extra property without its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, additionalProperties: false},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {location: 'Paris', secret: 'private-value'});

    expect({result: response.result, executorCalls}).toEqual({
      result: '/secret violates additionalProperties',
      executorCalls: 0,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#12
  it('recompiles a reused static schema at each registration', () => {
    const registry = new ToolRegistry();
    const location = {type: 'string'};
    const schema = {type: 'object', properties: {location}};
    registry.register({name: 'first', description: 'First', inputSchema: schema}, async () => 'first');
    location.type = 'not-a-json-schema-type';

    let errorMessage = '';
    try {
      registry.register({name: 'second', description: 'Second', inputSchema: schema}, async () => 'second');
    } catch (error) {
      errorMessage = (error as Error).message;
    }
    expect({errorMessage, registered: registry.has('second')}).toEqual({
      errorMessage: expect.stringMatching(/second/),
      registered: false,
    });
  });

  // specs/hal-engine-tool-input-validation/spec.md#15
  it('preserves a leading dot in an actual required property name', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {'.location': {type: 'string'}}, required: ['.location']},
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {});

    expect(response.result).toBe('/.location is required');
  });
});

